    const piece = this.board[oldPosition[0]][oldPosition[1]]
    const pieceType = this.pieceColor(piece)

    // Ensure the move is within bounds
    if (
      oldPosition[0] < 0 ||
      oldPosition[1] < 0 ||
      oldPosition[0] >= this.size ||
      oldPosition[1] >= this.size ||
      newPosition[0] < 0 ||
      newPosition[1] < 0 ||
      newPosition[0] >= this.size ||
