        // Vertical move considered
        return true
      } else {
        return false
      }
    }

    if (pieceType === 'R') {
      // Rook can only move horizontally or vertically any number of squares
      // Check if move is horizontal or vertical
      if (newPosition[0] === oldPosition[0] || newPosition[1] === oldPosition[1]) {
        return true
      } else {
        return false
      }
    }

    if (pieceType === 'B') {
      // Bishop moves diagonally any number of squares
      const dx = Math.abs(newPosition[1] - oldPosition[1])
